pub struct DiceSimulator {
    num_rolls: u32,
    outcomes: [u32; 11], // 2-12 possible outcomes
}

impl DiceSimulator {
    pub fn new(num_rolls: u32) -> Self {
        DiceSimulator {
            num_rolls,
            outcomes: [0; 11],
        }
    }

    pub fn run(&mut self) {
        // Perform dice rolls and update outcomes
        for _ in 0..self.num_rolls {
            let roll1: u32 = rand::random::<u32>() % 6 + 1;
            let roll2: u32 = rand::random::<u32>() % 6 + 1;
            let outcome = roll1 + roll2 - 2; // Adjust for 0-based indexing
            self.outcomes[outcome as usize] += 1;
        }
    }

    pub fn calculate_frequencies(&self) -> Vec<(u32, u32, f64)> {
        let mut frequencies = Vec::new();
        for (outcome, count) in self.outcomes.iter().enumerate() {
            let outcome = outcome as u32 + 2; // Adjust for 0-based indexing
            let frequency = (*count as f64 / self.num_rolls as f64) * 100.0;
            frequencies.push((outcome, *count, frequency));
        }
        frequencies
    }
}
